if(!defined('REDFOX_SKIP_BOTAPI_ROUTER'))define('REDFOX_SKIP_BOTAPI_ROUTER',true);require_once __DIR__.'/../lib/Security.php';redfox_secure_session_start();require_once __DIR__.'/../config.php';require_once __DIR__.'/lib/icons.php';$q=$pdo->prepare('SELECT * FROM admin WHERE username=? LIMIT 1');$q->execute([$_SESSION['user']??'']);$admin=$q->fetch(PDO::FETCH_ASSOC);if(!$admin){header('Location:login.php');exit;}if(($admin['rule']??'')!=='administrator'){http_response_code(403);exit;}try{rx_require_schema($pdo,['reseller_broadcasts','reseller_message_queue','reseller_api_keys'],['reseller_api_keys'=>['ip_allowlist']]);}catch(Throwable$e){header('Location:migrations.php?required=reseller_security');exit;}$flash='';$ft='success';
if(($_SERVER['REQUEST_METHOD']??'')==='POST'){$act=(string)($_POST['action']??'');try{if($act==='cancel_broadcast'){$id=(string)($_POST['id']??'');$pdo->beginTransaction();$pdo->prepare("UPDATE reseller_broadcasts SET status='cancelled',completed_at=? WHERE broadcast_id=? AND status IN ('queued','processing')")->execute([time(),$id]);$pdo->prepare("UPDATE reseller_message_queue SET status='cancelled',claim_token=NULL,claimed_at=NULL WHERE broadcast_id=? AND status IN ('queued','retry','processing')")->execute([$id]);$pdo->commit();$flash='صف پیام لغو شد.';}elseif($act==='revoke_key'){$pdo->prepare('UPDATE reseller_api_keys SET revoked_at=? WHERE id=? AND revoked_at IS NULL')->execute([time(),(int)($_POST['id']??0)]);$flash='کلید API فوراً لغو شد.';}elseif(in_array($act,['queue_retry','queue_mark_sent'],true)){$id=(int)($_POST['id']??0);$bq=$pdo->prepare('SELECT broadcast_id FROM reseller_message_queue WHERE id=?');$bq->execute([$id]);$bid=(string)$bq->fetchColumn();$status=$act==='queue_retry'?'retry':'sent';$q=$pdo->prepare("UPDATE reseller_message_queue SET status=?,next_attempt_at=?,sent_at=?,last_error=NULL WHERE id=? AND status='needs_reconcile'");$q->execute([$status,$status==='retry'?time():0,$status==='sent'?time():null,$id]);if($q->rowCount()&&$bid!==''){$c=$pdo->prepare("SELECT SUM(status='sent'),SUM(status='failed'),SUM(status IN ('queued','retry','processing','needs_reconcile')) FROM reseller_message_queue WHERE broadcast_id=?");$c->execute([$bid]);$v=$c->fetch(PDO::FETCH_NUM);$pdo->prepare("UPDATE reseller_broadcasts SET sent_count=?,failed_count=?,status=? WHERE broadcast_id=? AND status<>'cancelled'")->execute([(int)$v[0],(int)$v[1],(int)$v[2]>0?'processing':'completed',$bid]);}$flash=$q->rowCount()?'پیام تطبیق شد.':'رکورد قابل تطبیق نیست.';}try{$pdo->prepare('INSERT INTO audit_log(admin_user,action,entity,details,ip,created_at) VALUES(?,?,?,?,?,?)')->execute([$admin['username'],'reseller_security.'.$act,(string)($_POST['id']??''),'{}',redfox_client_ip(),date('c')]);}catch(Throwable$e){}}catch(Throwable$e){if($pdo->inTransaction())$pdo->rollBack();$flash=redfox_public_exception($e, 'panel/reseller_security.php');$ft='error';}}
$tab=in_array((string)($_GET['tab']??'messages'),['messages','reconcile','api'],true)?$_GET['tab']:'messages';$status=trim((string)($_GET['status']??''));$search=trim((string)($_GET['q']??''));$params=[];$where='1=1';if($status!==''){$where.=' AND status=?';$params[]=$status;}if($search!==''){$where.=' AND (actor_reseller_id LIKE ? OR title LIKE ? OR broadcast_id LIKE ?)';$like='%'.$search.'%';array_push($params,$like,$like,$like);}$q=$pdo->prepare("SELECT * FROM reseller_broadcasts WHERE $where ORDER BY created_at DESC LIMIT 200");$q->execute($params);$broadcasts=$q->fetchAll(PDO::FETCH_ASSOC);$reconcile=$pdo->query("SELECT q.*,b.actor_reseller_id,b.title FROM reseller_message_queue q JOIN reseller_broadcasts b ON b.broadcast_id=q.broadcast_id WHERE q.status='needs_reconcile' ORDER BY q.id DESC LIMIT 200")->fetchAll(PDO::FETCH_ASSOC);$keys=$pdo->query('SELECT k.*,u.username FROM reseller_api_keys k LEFT JOIN user u ON u.id=k.reseller_id ORDER BY k.id DESC LIMIT 300')->fetchAll(PDO::FETCH_ASSOC);$stats=['queued'=>(int)$pdo->query("SELECT COUNT(*) FROM reseller_message_queue WHERE status IN ('queued','retry','processing')")->fetchColumn(),'sent'=>(int)$pdo->query("SELECT COUNT(*) FROM reseller_message_queue WHERE status='sent'")->fetchColumn(),'failed'=>(int)$pdo->query("SELECT COUNT(*) FROM reseller_message_queue WHERE status='failed'")->fetchColumn(),'reconcile'=>count($reconcile),'keys'=>(int)$pdo->query('SELECT COUNT(*) FROM reseller_api_keys WHERE revoked_at IS NULL AND expires_at>'.time())->fetchColumn()];
$statusLabels=['queued'=>'در صف','retry'=>'تلاش مجدد','processing'=>'در حال پردازش','completed'=>'تکمیل‌شده','cancelled'=>'لغوشده','sent'=>'ارسال‌شده','failed'=>'ناموفق','needs_reconcile'=>'نیازمند بررسی'];$kindLabels=['broadcast'=>'همگانی','direct'=>'مستقیم'];$permLabels=['stats'=>'آمار','customers'=>'مشتریان','invoices'=>'سفارش‌ها','message_write'=>'ارسال پیام','service_write'=>'عملیات سرویس','product_write'=>'محصولات','settlement_write'=>'واریز نماینده'];
?><!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>پیام و API نمایندگان</title><link rel="stylesheet" href="css/theme.css"><style>.sec-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:12px}.sec-stat{padding:16px;border:1px solid var(--border-soft);background:var(--surface-1);border-radius:13px}.sec-stat b{display:block;font-size:24px}.tabs{display:flex;gap:6px;margin:16px 0;flex-wrap:wrap}.tabs a{padding:9px 15px;border-radius:9px;background:var(--surface-1);color:var(--text-muted);text-decoration:none}.tabs a.active{background:var(--accent);color:var(--accent-fg)}.perm{display:inline-block;padding:2px 7px;border-radius:10px;background:var(--accent-soft);font-size:10px;margin:2px}.status{padding:3px 8px;border-radius:12px;background:var(--surface-2);font-size:11px}.ok{color:var(--color-success)}.bad{color:var(--color-danger)}</style></head><body><section id="container"><?php include'header.php';?><section id="main-content"><div class="wrapper"><div class="page-head"><h1 class="page-head__title">مرکز پیام و API نمایندگان</h1><div class="page-head__sub">صف ارسال، تطبیق پردازشگر، کلیدهای محدود به نماینده و لغو فوری</div></div><?php if($flash):?><div class="card <?=$ft==='error'?'bad':'ok'?>"><?=htmlspecialchars($flash)?></div><?php endif;?><div class="page-guide">پیام‌های نمایندگان در صف Cron ارسال می‌شوند. کلید API فقط به داده‌های همان نماینده دسترسی دارد و از این صفحه می‌توانید صف‌ها، خطاهای نامطمئن و کلیدهای فعال را کنترل کنید.</div><div class="sec-grid"><div class="sec-stat"><b><?=$stats['queued']?></b>در صف/پردازش</div><div class="sec-stat"><b><?=$stats['sent']?></b>ارسال موفق</div><div class="sec-stat"><b><?=$stats['failed']?></b>ناموفق</div><div class="sec-stat"><b><?=$stats['reconcile']?></b>نیازمند تطبیق</div><div class="sec-stat"><b><?=$stats['keys']?></b>کلید API فعال</div></div><div class="tabs"><a href="?tab=messages" class="<?=$tab==='messages'?'active':''?>">📣 صف‌های پیام</a><a href="?tab=reconcile" class="<?=$tab==='reconcile'?'active':''?>">⚠️ تطبیق پیام</a><a href="?tab=api" class="<?=$tab==='api'?'active':''?>">🔑 کلیدهای API</a><a href="reseller_permissions.php">⚙️ دسترسی نمایندگان</a></div><?php if($tab==='messages'):?><div class="card"><form method="get"><input type="hidden" name="tab" value="messages"><input name="q" value="<?=htmlspecialchars($search)?>" placeholder="نماینده، عنوان یا شناسه صف"><select name="status"><option value="">همه وضعیت‌ها</option><?php foreach(['queued','processing','completed','cancelled']as$s):?><option value="<?=$s?>" <?=$status===$s?'selected':''?>><?=htmlspecialchars($statusLabels[$s]??$s)?></option><?php endforeach;?></select><button class="btn">فیلتر</button></form><div class="table-wrap"><table class="app-table"><tr><th>زمان/شناسه</th><th>نماینده</th><th>نوع/عنوان</th><th>پیشرفت</th><th>وضعیت</th><th>عملیات</th></tr><?php foreach($broadcasts as$r):$pct=$r['total_count']?round(((int)$r['sent_count']+(int)$r['failed_count'])/(int)$r['total_count']*100):0;?><tr><td><?=date('Y/m/d H:i',(int)$r['created_at'])?><br><code><?=htmlspecialchars(substr($r['broadcast_id'],0,12))?>…</code></td><td><a href="reseller_report.php?id=<?=$r['actor_reseller_id']?>">#<?=$r['actor_reseller_id']?></a></td><td><?=htmlspecialchars($kindLabels[$r['kind']]??$r['kind'])?> / <?=htmlspecialchars($r['title'])?></td><td><?=$r['sent_count']?> موفق · <?=$r['failed_count']?> خطا · <?=$pct?>٪</td><td><span class="status"><?=htmlspecialchars($statusLabels[$r['status']]??$r['status'])?></span></td><td><?php if(in_array($r['status'],['queued','processing'],true)):?><form method="post"><input type="hidden" name="action" value="cancel_broadcast"><input type="hidden" name="id" value="<?=$r['broadcast_id']?>"><button class="btn btn-sm btn-danger" onclick="return confirm('کل صف لغو شود؟')">لغو صف</button></form><?php endif;?></td></tr><?php endforeach;?></table></div></div><?php elseif($tab==='reconcile'):?><div class="card"><h2>پیام‌های نامطمئن پس از قطع پردازشگر</h2><p>قبل از Retry بررسی کنید؛ ممکن است Telegram پیام را دریافت کرده ولی پردازشگر قبل از ثبت نتیجه قطع شده باشد.</p><table class="app-table"><tr><th>ID</th><th>نماینده</th><th>مخاطب</th><th>عنوان</th><th>خطا</th><th>تصمیم</th></tr><?php foreach($reconcile as$r):?><tr><td><?=$r['id']?></td><td>#<?=$r['actor_reseller_id']?></td><td><?=$r['recipient_user_id']?></td><td><?=htmlspecialchars($r['title'])?></td><td><?=htmlspecialchars($r['last_error'])?></td><td><form method="post"><input type="hidden" name="id" value="<?=$r['id']?>"><button name="action" value="queue_mark_sent" class="btn btn-success btn-sm">قبلاً ارسال شده</button><button name="action" value="queue_retry" class="btn btn-warning btn-sm" onclick="return confirm('احتمال ارسال تکراری وجود دارد. ادامه؟')">تلاش مجدد</button></form></td></tr><?php endforeach;?></table></div><?php else:?><div class="card"><h2>کلیدهای API نمایندگان</h2><div class="table-wrap"><table class="app-table"><tr><th>نماینده</th><th>نام/پیشوند</th><th>دسترسی‌ها</th><th>فهرست IP مجاز</th><th>مصرف/انقضا</th><th>وضعیت</th><th></th></tr><?php foreach($keys as$k):$perms=json_decode((string)$k['permissions'],true)?:[];$ips=json_decode((string)($k['ip_allowlist']??'[]'),true)?:[];$active=!$k['revoked_at']&&(int)$k['expires_at']>time();?><tr><td>#<?=$k['reseller_id']?> @<?=htmlspecialchars($k['username'])?></td><td><?=htmlspecialchars($k['name'])?><br><code><?=htmlspecialchars($k['key_prefix'])?>…</code></td><td><?php foreach($perms as$p):?><span class="perm"><?=htmlspecialchars($permLabels[$p]??$p)?></span><?php endforeach;?></td><td><?=htmlspecialchars($ips?implode(', ',$ips):'بدون محدودیت')?></td><td>آخرین: <?=$k['last_used_at']?date('Y/m/d H:i',(int)$k['last_used_at']):'هرگز'?><br>انقضا: <?=date('Y/m/d',(int)$k['expires_at'])?></td><td class="<?=$active?'ok':'bad'?>"><?=$active?'فعال':($k['revoked_at']?'لغوشده':'منقضی')?></td><td><?php if($active):?><form method="post"><input type="hidden" name="action" value="revoke_key"><input type="hidden" name="id" value="<?=$k['id']?>"><button class="btn btn-danger btn-sm" onclick="return confirm('کلید فوراً لغو شود؟')">لغو فوری</button></form><?php endif;?></td></tr><?php endforeach;?></table></div></div><?php endif;?></div></section></section></body></html>
